<?php require __DIR__.'/includes/bootstrap.php';$title='ASMR Equipment';$rows=$pdo?$pdo->query("SELECT * FROM products WHERE status='published' ORDER BY featured DESC,product_name")->fetchAll():[];require __DIR__.'/includes/header.php';?><div class="container"><h1>ASMR Equipment</h1><p class="muted">Carefully selected equipment for better listening and recording.</p><div class="grid"><?php foreach($rows as $p):?><article class="card"><h2><a href="<?=url('products/'.$p['slug'].'/')?>"><?=e($p['product_name'])?></a></h2><?php if($p['brand']):?><p class="muted"><?=e($p['brand'])?></p><?php endif;?><p><?=e($p['short_description']??'')?></p><?php if($p['best_for']):?><p><strong>Best for:</strong> <?=e($p['best_for'])?></p><?php endif;?><?php if($p['price_text']):?><p><?=e($p['price_text'])?></p><?php endif;?><a class="btn" href="<?=url('go/'.$p['slug'].'/') ?>" target="_blank" rel="nofollow sponsored noopener"><?=e($p['button_text']??'View product')?></a><small class="muted" style="display:block;margin-top:12px">ASMR Audio Online may earn a commission at no additional cost to you.</small></article><?php endforeach;?></div><?php if(!$rows):?><p class="muted">No products are available yet.</p><?php endif;?></div><?php require __DIR__.'/includes/footer.php';
